  if(scene==='story'){$('brandName').oninput=e=>{project.brandName=e.target.value;invalidate();delayedSave();};$('brandFacts').oninput=e=>{project.brandFacts=e.target.value;invalidate();delayedSave();};$('chooseBrand').onclick=()=>{modal('<h2>选择品牌资料</h2>'+data.assets.filter(a=>a.type==='brand'&&!a.archived).map(a=>`<button data-brand="${a.id}">${esc(a.name)}</button>`).join(''));document.querySelectorAll('[data-brand]').forEach(b=>b.onclick=()=>{const a=assetById(b.dataset.brand);project.brandName=a.name;project.brandFacts=a.materials;invalidate();save();$('modal').close();renderStudio();});};}
  if($('applyCommon'))$('applyCommon').onclick=async()=>{const id=$('commonSource').value;if(!id||!project.plans.length){toast('请先选择模板与底图。');return;}for(const p of project.plans){p.imageIds=[id];p.mapping='common';invalidate(p);}await save();renderStudio();toast('已按共用模式分配底图，数量保持不变。');};
