  renderTemplateGrid();$('templateSearch').oninput=e=>{query=e.target.value;renderTemplateGrid();};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderStudio();});$('newTemplate').onclick=()=>editTemplate(null);
  renderBottom();
