  document.querySelectorAll('[data-select]').forEach(c=>c.onchange=()=>{if(c.checked){const t=templateById(c.dataset.select),route=data.routes.find(r=>r.id===(data.settings.defaultRoute||'doubao'))||data.routes.find(r=>r.configured);project.plans.push({id:crypto.randomUUID(),templateId:t.id,count:1,duration:t.duration,videoRoute:route.id,resolution:route.resolutions[0],mapping:t.mapping,imageIds:localStorage.getItem('studio:pendingAsset')?[localStorage.getItem('studio:pendingAsset')]:[],rows:[],shotImages:[],creativeBrief:'',content:'',prompts:[],snapshot:t,scriptConfirmed:false});}else project.plans=project.plans.filter(p=>p.templateId!==c.dataset.select);localStorage.removeItem('studio:pendingAsset');save();renderTemplateGrid();renderBottom();});
