  document.querySelectorAll('[data-prompt]').forEach(e=>e.oninput=()=>{const [id,index]=e.dataset.prompt.split(':');selectedPlan(id).prompts[index]=e.value;clearTimeout(promptSaveTimer);promptSaveTimer=setTimeout(()=>persistPrompts().catch(e=>toast(e.message)),600);});
