async function persistPrompts(confirm=false){await saveChain.catch(()=>{});return post(`/studio/projects/${project.id}/prompts`,{confirm,plans:project.plans.filter(p=>p.prompts.length===p.count&&p.prompts.every(Boolean)).map(p=>({id:p.id,prompts:p.prompts,scriptConfirmed:p.scriptConfirmed}))});}
async function submitDialog(trial){try{
  await persistPrompts(true);const current=await api('/studio/projects/'+project.id);if(!trial&&current.readiness.errors.length)throw Error(current.readiness.errors.join('；'));
  const adopted=current.adopted.length,total=current.readiness.count;
  modal(`<h2>${trial?'选择一个画面试片':'确认批量制作'}</h2><p>${trial?'本次只生成一条，完成后可在我的作品采纳。':`计划 ${total} 条，采纳试片 ${adopted} 条，本次提交 ${total-adopted} 条。`}</p>${trial?`<label class="field">试片画面<select id="trialSlot">${project.plans.flatMap(p=>Array.from({length:p.count},(_,i)=>`<option value="${p.id}:${i}">${esc(p.snapshot.name)} · 画面 ${i+1}</option>`)).join('')}</select></label>`:project.plans.map(p=>`<details><summary>${esc(p.snapshot.name)} · ${p.count} 条 · ${p.duration} 秒</summary>${mappedSlots(p).map((ids,i)=>`<p>画面 ${i+1}：${ids.map(id=>esc(assetById(id)?.name||id)).join('、')}</p>`).join('')}</details>`).join('')}<div class="notice">任务将使用已配置的生成服务。没有可用账号时保持排队；费用以生成服务实际计费为准。</div><button id="confirmSubmit" class="primary">${trial?'生成 1 条试片':'确认提交 '+(total-adopted)+' 条'}</button>`);
  const requestId=crypto.randomUUID();$('confirmSubmit').onclick=async()=>{const button=$('confirmSubmit');button.disabled=true;try{const [planId,index]=$('trialSlot')?.value.split(':')||[];await post(`/studio/projects/${project.id}/submit`,{trial,planId,index:Number(index),requestId});location.href='/works?project='+project.id;}catch(e){toast(e.message);button.disabled=false;}};
}catch(e){toast(e.message);}}
function imageWorkbench(plan){
  modal(`<h2>底图准备 · ${esc(plan.snapshot.name)}</h2><p>${esc(plan.snapshot.imageRules)}</p><div class="notice">生成的底图会自动存入我的素材，确认人物、姿态和构图后才能使用。</div><label class="field">图片分配方式<select id="mapping">${options([{id:'common',name:'共用一张底图'},{id:'one-to-one',name:'每条视频独立底图'},{id:'custom',name:'自定义数量分配'},{id:'shots',name:'按分镜分配'}],plan.mapping)}</select></label><div class="row"><button id="uploadBase">＋ 上传底图</button><button id="generateBase">✧ 按模板生成底图</button><button id="referenceBase">✧ 基于参考图生成</button></div><p class="muted">${plan.count} 条视频 · 已选 ${plan.imageIds.length} 张；减少数量时，多余素材仍保留。</p><div class="grid" id="imageOptions">${data.assets.filter(a=>['upload','generated'].includes(a.type)&&!a.archived).map(a=>`<div class="card asset-choice"><label><input type="checkbox" data-image="${a.id}" ${plan.imageIds.includes(a.id)?'checked':''}><img src="${esc(a.previewUrl)}" loading="lazy" alt="${esc(a.name)}"><h3>${esc(a.name)}</h3><span class="badge">${a.confirmed===false?'待确认':'可使用'}</span></label><div class="body asset-actions"><button data-image-preview="${a.id}">放大 / 确认</button>${a.confirmed===false?`<button data-confirm-image="${a.id}">确认底图</button>`:''}</div></div>`).join('')}</div><div id="mappingRows"></div><div class="row" style="margin-top:20px"><button id="confirmMapping" class="primary">确认图片与分配</button></div>`);
  $('mapping').onchange=()=>{if(plan.mapping!==$('mapping').value)toast('分配方式已更改，原图片和内容保留，请检查对应关系。');renderMappingRows(plan);};
  const selectedImages=()=>[...document.querySelectorAll('[data-image]:checked')].map(e=>e.dataset.image);
  document.querySelectorAll('[data-image]').forEach(e=>e.onchange=()=>renderMappingRows({...plan,imageIds:selectedImages()}));
  $('uploadBase').onclick=()=>uploadImage(async a=>{plan.imageIds.push(a.id);await save();imageWorkbench(plan);});
  $('generateBase').onclick=()=>generateImageDialog(plan,false);$('referenceBase').onclick=()=>generateImageDialog(plan,true);
  document.querySelectorAll('[data-image-preview]').forEach(b=>b.onclick=()=>imagePreview(b.dataset.imagePreview,()=>imageWorkbench(plan)));
  document.querySelectorAll('[data-confirm-image]').forEach(b=>b.onclick=async()=>{try{await api('/studio/assets/'+b.dataset.confirmImage,{method:'PATCH',body:{confirmed:true,scene}});data=await api('/studio');imageWorkbench(plan);}catch(e){toast(e.message);}});
  renderMappingRows(plan);
  $('confirmMapping').onclick=async()=>{try{
    const ids=selectedImages(),mapping=$('mapping').value;
    if(!ids.length)throw Error('请选择图片');if(ids.some(id=>assetById(id)?.confirmed===false))throw Error('请先放大查看并确认生成底图');
    plan.imageIds=ids;plan.mapping=mapping;
    if(mapping==='custom'){plan.rows=[...document.querySelectorAll('[data-map-image]')].map((e,i)=>({imageId:e.value,count:Number(document.querySelectorAll('[data-map-count]')[i].value)}));const sum=plan.rows.reduce((n,r)=>n+r.count,0);if(!Number.isInteger(sum)||sum<1||sum>100||plan.rows.some(r=>!Number.isInteger(r.count)||r.count<1))throw Error('自定义分配的合计须为1–100条');plan.count=sum;}
    if(mapping==='shots'){plan.shotImages=Array.from({length:plan.count},(_,i)=>[...document.querySelectorAll(`[data-shot-slot="${i}"]:checked`)].map(e=>e.value));if(plan.shotImages.some(v=>!v.length))throw Error('请为每个画面分配至少一张分镜图片');}
    invalidate(plan);await save();$('modal').close();renderStudio();toast('底图分配已保存，请生成与新底图对应的提示词。');
  }catch(e){toast(e.message);}};
}
function renderMappingRows(plan){const mode=$('mapping').value,ids=[...document.querySelectorAll('[data-image]:checked')].map(e=>e.dataset.image);if(mode==='custom')$('mappingRows').innerHTML=`<h3>数量分配 · 合计作为模板的视频数量</h3>${ids.map((id,i)=>`<div class="mapping-row"><select data-map-image>${options(ids.map(v=>({id:v,name:assetById(v)?.name})),id)}</select><input data-map-count type="number" min="1" value="${plan.rows.find(r=>r.imageId===id)?.count||1}"><span>条</span></div>`).join('')}`;else if(mode==='shots')$('mappingRows').innerHTML=`<h3>分镜图片对应</h3>${Array.from({length:plan.count},(_,i)=>`<details><summary>画面 ${i+1}</summary>${ids.map(id=>`<label class="field"><input type="checkbox" data-shot-slot="${i}" value="${id}" ${(plan.shotImages?.[i]||[]).includes(id)?'checked':''}> ${esc(assetById(id)?.name)}</label>`).join('')}</details>`).join('')}`;else $('mappingRows').innerHTML=`<p class="notice">${mode==='one-to-one'?`按选中顺序对应画面，需要 ${plan.count} 张独立图片。`:'所有视频使用第一张选中的底图，合计视频数量不会增加。'}</p>`;}
function uploadImage(callback){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});const ref=await post('/references',{name:file.name,mime:file.type,base64,purpose:'store-background'});await api('/studio/assets/'+ref.id,{method:'PATCH',body:{confirmed:true,scene:scene||''}});data=await api('/studio');callback?.(ref);toast('图片已保存到我的素材。');}catch(e){toast(e.message);}};input.click();}
function imagePreview(id,back){const a=assetById(id);modal(`<h2>${esc(a.name)}</h2><img class="big-preview" src="${esc(a.previewUrl)}" alt="${esc(a.name)}"><p>${a.confirmed===false?'请核对成年人物、起始姿态、接触部位和构图。':'已确认素材'}</p><p class="muted">${a.derivedFrom?'参考来源：'+esc(assetById(a.derivedFrom)?.name||a.derivedFrom)+' · ':''}${a.templateId?'模板：'+esc(templateById(a.templateId)?.name||a.templateId):'历史来源待归类'}${a.projectId?' · 项目：'+esc(data.projects.find(p=>p.id===a.projectId)?.name||a.projectId):''}${a.templateVersion?' · 模板版本 '+a.templateVersion:''}</p>${a.generationDescription?`<details><summary>底图生成描述</summary><p>${esc(a.generationDescription)}</p></details>`:''}<div class="row"><button id="confirmAsset" class="primary">确认底图</button><button id="backImages">返回选择 / 替换</button><button id="analyzeImage">分析空间条件</button>${a.type==='generated'&&a.projectId?'<button id="redoImage">重做底图（保存新素材）</button>':''}</div>`);$('confirmAsset').onclick=async()=>{await api('/studio/assets/'+id,{method:'PATCH',body:{confirmed:true}});data=await api('/studio');back?.();};$('backImages').onclick=()=>back?back():$('modal').close();if($('redoImage'))$('redoImage').onclick=async()=>{try{const source=await api('/studio/projects/'+a.projectId);const plan=source.plans.find(p=>p.templateId===a.templateId);if(!plan)throw Error('原项目模板已移除，请重新选择模板制作');const task=await post('/studio/images',{projectId:source.id,planId:plan.id,count:1,referenceId:a.derivedFrom||'',requestId:crypto.randomUUID()});toast('已提交一张重做底图，原图保留。可在我的素材查看生成结果。');$('modal').close();}catch(e){toast(e.message);}};$('analyzeImage').onclick=async()=>{try{$('analyzeImage').disabled=true;toast('正在分析底图中的空间与房门…');await post('/references/'+id+'/analyze',{});data=await api('/studio');toast('空间分析已完成。');}catch(e){toast(e.message);}finally{$('analyzeImage')&&($('analyzeImage').disabled=false);}};}
function generateImageDialog(plan,reference){modal(`<h2>${reference?'基于参考图生成':'按模板生成底图'}</h2><label class="field">生成数量<input id="imageCount" type="number" min="1" max="30" value="${plan.mapping==='common'?1:plan.count}"></label>${reference?`<label class="field">风格 / 构图参考（不作为视频初始图片）<select id="sourceImage">${options(data.assets.filter(a=>a.previewUrl&&a.type!=='reference-video').map(a=>({id:a.id,name:a.name})))}</select></label>`:''}<label class="field">补充想法（选填）<textarea id="imageBrief">${esc(plan.creativeBrief)}</textarea></label><p class="notice">点击后提交实际图片生成任务。每张图片保留为新素材，确认后再分配到视频。</p><button id="runImages" class="primary">确认生成底图</button>`);$('runImages').onclick=async()=>{try{await save();$('runImages').disabled=true;const task=await post('/studio/images',{projectId:project.id,planId:plan.id,count:Number($('imageCount').value),brief:$('imageBrief').value,referenceId:$('sourceImage')?.value,requestId:crypto.randomUUID()});localStorage.setItem('studio:images:'+project.id,task.id);$('modal').close();toast('底图任务已提交，生成后到我的素材确认。');pollImages(task.id);}catch(e){toast(e.message);$('runImages')&&($('runImages').disabled=false);}};}
async function pollImages(id){try{const task=await api('/studio/image-tasks/'+id);if(task.status==='complete'){data=await api('/studio');localStorage.removeItem('studio:images:'+project.id);toast('底图已保存到我的素材，请确认后使用。');}else if(task.status==='error'){toast(task.error);localStorage.removeItem('studio:images:'+project.id);}else setTimeout(()=>pollImages(id),4000);}catch(e){toast(e.message);}}
function editTemplate(t,plan){
  const current=structuredClone(t||{name:'',scene:scene||'footspa',description:'',imageRules:'',people:'成年人',actions:[],duration:5,mapping:'common'});
  modal(`<h2>${t?'编辑模板内容':'新建模板'}</h2><label class="field">模板名称<input id="editName" value="${esc(current.name)}"></label><label class="field">适用场景<select id="editScene"><option value="" ${!current.scene?'selected':''}>通用制作 · 暂不绑定场景</option>${options(data.scenes,current.scene)}</select></label><label class="field">底图要求<textarea id="editImageRules">${esc(current.imageRules)}</textarea></label><label class="field">人物<input id="editPeople" value="${esc(current.people)}"></label><h3>动作顺序</h3><div id="actionsEditor"></div><button id="addAction">＋ 增加动作</button><div class="notice warning" id="densityWarning" hidden>短时长容纳过多动作容易失真，建议精简或延长时长。</div><label class="field">视频内容<textarea id="editDescription">${esc(current.description)}</textarea></label><div class="fields"><label class="field">推荐时长<input id="editDuration" type="number" min="2" max="60" value="${current.duration}"></label><label class="field">默认图片分配<select id="editMapping">${options([{id:'common',name:'共用一张'},{id:'one-to-one',name:'每条独立'},{id:'custom',name:'自定义'},{id:'shots',name:'按分镜'}],current.mapping)}</select></label></div>${plan&&current.scene==='story'&&plan.prompts.length?`<details><summary>本项目脚本与分镜</summary>${plan.prompts.map((p,i)=>`<p style="white-space:pre-wrap"><strong>画面 ${i+1}</strong><br>${esc(p)}</p>`).join('')}</details>`:''}<details><summary>详细提示词约束</summary><p>${esc(current.description)}</p></details><div class="row" style="margin-top:24px">${plan?'<button id="applyProject" class="primary">仅应用本项目</button>':''}<button id="saveTemplate" class="${plan?'':'primary'}">${t?.source==='builtin'?'另存为我的模板':t?'保存新版本':'保存模板'}</button>${t&&t.source!=='builtin'?'<button id="copyTemplate">另存副本</button>':''}</div>`,true);
  function actions(){ $('actionsEditor').innerHTML=current.actions.map((a,i)=>`<div class="action-row"><span>${i+1}</span><textarea data-action="${i}">${esc(a)}</textarea><button data-up="${i}" aria-label="上移动作">↑</button><button data-down="${i}" aria-label="下移动作">↓</button><button data-delete-action="${i}" aria-label="删除动作">×</button></div>`).join('');document.querySelectorAll('[data-action]').forEach(e=>e.oninput=()=>current.actions[e.dataset.action]=e.value);document.querySelectorAll('[data-up],[data-down],[data-delete-action]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.up??b.dataset.down??b.dataset.deleteAction);if(b.dataset.deleteAction!==undefined)current.actions.splice(i,1);else{const n=i+(b.dataset.up!==undefined?-1:1);if(n>=0&&n<current.actions.length)[current.actions[i],current.actions[n]]=[current.actions[n],current.actions[i]];}actions();});$('densityWarning').hidden=current.actions.length<=2||Number($('editDuration').value)>10;}
  actions();$('addAction').onclick=()=>{current.actions.push('');actions();};$('editDuration').oninput=actions;
  const read=()=>({...current,name:$('editName').value,scene:$('editScene').value,imageRules:$('editImageRules').value,people:$('editPeople').value,description:$('editDescription').value,actions:current.actions.filter(Boolean),duration:Number($('editDuration').value),mapping:$('editMapping').value});
  if(plan)$('applyProject').onclick=async()=>{const changed=read();plan.snapshot=changed;plan.content=changed.description;plan.duration=changed.duration;invalidate(plan);await save();$('modal').close();renderStudio();};
  const store=async copy=>{try{await post('/studio/templates',{...read(),copy:copy||t?.source==='builtin'});data=await api('/studio');$('modal').close();page==='/templates'?templateCenter():renderStudio();toast('模板已保存；历史版本与已提交作品保留。');}catch(e){toast(e.message);}};
  $('saveTemplate').onclick=()=>store(false);if($('copyTemplate'))$('copyTemplate').onclick=()=>store(true);
}
function bindTemplatePreviews(){window.VideoCards?.observe();document.querySelectorAll('[data-preview-template]').forEach(b=>b.onclick=async()=>{const t=templateById(b.dataset.previewTemplate);try{if(t.example){const example=t.example;if(example){window.VideoPreview?.openExample?.(example);if(example.videoUrl){modal(`<h2>${esc(t.name)}</h2><video controls preload="metadata" class="big-preview" src="${esc(example.videoUrl)}"></video>`);return;}}}modal(`<h2>${esc(t.name)}</h2><p>${esc(t.imageRules)}</p><p>${esc(t.description)}</p><span class="badge">推荐 ${t.duration} 秒</span><p class="muted">暂无已绑定的示例视频。实际生成的作品可保留为模板示例。</p>`);}catch(e){toast(e.message);}});}
function templateCenter(){
  $('app').innerHTML=title('模板中心','内置模板、你的创作与复刻结果，都可以在这里继续制作。')+`<div class="toolbar filters">${[{id:'all',name:'全部'},{id:'builtin',name:'内置模板'},{id:'my',name:'我的模板'},{id:'replica',name:'复刻模板'},{id:'archived',name:'已归档'}].map(f=>`<button data-source="${f.id}" class="${filter===f.id?'active':''}">${f.name}</button>`).join('')}<input id="centerSearch" placeholder="搜索模板" value="${esc(query)}"><select id="sceneFilter" style="width:150px"><option value="">全部场景</option>${options(data.scenes,scene)}</select><a class="button" href="/production">管理动作包</a><button id="newCenter" class="primary">＋ 新建模板</button></div><div id="centerGrid" class="grid"></div>`;
  function render(){const list=data.templates.filter(t=>(filter==='archived'?t.archived:!t.archived)&&(filter==='all'||filter==='archived'||t.source===filter)&&(!scene||t.scene===scene)&&(t.name+t.description).includes(query));$('centerGrid').innerHTML=list.map(t=>`<article class="card">${cover(t)}<div class="body"><h3>${esc(t.name)}</h3><p>${esc(t.description.slice(0,85))}</p><p class="muted">${esc(data.scenes.find(s=>s.id===t.scene)?.name||'通用复刻')} · ${t.duration} 秒 · 版本 ${t.version}</p><div class="row"><a class="button primary" href="${'/studio?scene='+t.scene+'&template='+encodeURIComponent(t.id)}">使用模板</a><button data-center-edit="${esc(t.id)}">编辑 / 复制</button><button data-archive="${esc(t.id)}" aria-label="归档模板">${t.archived?'恢复':'归档'}</button></div></div></article>`).join('')||'<div class="empty">没有符合条件的模板。</div>';bindTemplatePreviews();document.querySelectorAll('[data-center-edit]').forEach(b=>b.onclick=()=>editTemplate(templateById(b.dataset.centerEdit)));document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=async()=>{await api('/studio/templates/'+encodeURIComponent(b.dataset.archive),{method:'PATCH',body:{archived:!templateById(b.dataset.archive).archived}});data=await api('/studio');render();toast('模板状态已更新，历史作品的模板快照保留。');});}
  $('centerSearch').oninput=e=>{query=e.target.value;render();};$('sceneFilter').onchange=e=>{scene=e.target.value;render();};document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{filter=b.dataset.source;templateCenter();});$('newCenter').onclick=()=>editTemplate(null);render();
}
function assetsPage(){
  $('app').innerHTML=title('我的素材','图片、参考视频与品牌资料保存在本机，可重复用于制作。')+`<div class="toolbar filters">${[{id:'all',name:'全部'},{id:'upload',name:'上传图片'},{id:'generated',name:'生成底图'},{id:'reference-video',name:'参考视频'},{id:'brand',name:'品牌资料'},{id:'archived',name:'已归档'}].map(f=>`<button data-type="${f.id}" class="${filter===f.id?'active':''}">${f.name}</button>`).join('')}<input id="assetSearch" placeholder="搜索素材" value="${esc(query)}"><select id="assetScene" style="width:150px"><option value="">全部场景</option><option value="unclassified" ${assetScene==='unclassified'?'selected':''}>待归类</option>${options(data.scenes,assetScene)}</select><button id="assetUpload">＋ 上传图片</button><button id="brandUpload">＋ 品牌资料</button><a class="button primary" href="/studio">✧ 选择模板生成底图</a></div><div class="grid" id="assetGrid"></div>${data.imageTasks?.length?`<section class="work-group"><h2>底图生成任务</h2>${data.imageTasks.map(t=>`<details><summary>${esc(data.projects.find(p=>p.id===t.projectId)?.name||'历史项目')} · 已完成 ${t.items.filter(i=>i.status==='complete').length}/${t.items.length} 张 · ${new Date(t.createdAt).toLocaleString()}</summary>${t.items.map(i=>`<p>${esc(i.name)} · ${esc(statusNames[i.status]||({downloading:'保存中'})[i.status]||i.status)} ${i.error?esc(i.error):''} ${['error','needs_review'].includes(i.status)?`<button data-image-retry="${t.id}:${i.id}" data-unknown="${i.status==='needs_review'}">${i.status==='needs_review'?'核对上游编号':'重试这一张'}</button>`:''}</p>`).join('')}</details>`).join('')}</section>`:''}`;
  function render(){const list=data.assets.filter(a=>(filter==='archived'?a.archived:!a.archived)&&(filter==='all'||filter==='archived'||a.type===filter)&&(assetScene==='unclassified'?!a.scene:!assetScene||a.scene===assetScene)&&String(a.name).includes(query));$('assetGrid').innerHTML=list.map(a=>`<article class="card"><div class="cover">${a.previewUrl?`<img loading="lazy" src="${esc(a.previewUrl)}" alt="${esc(a.name)}">`:sceneArt('story')}<span class="badge">${a.confirmed===false?'待确认':{upload:'上传图片',generated:'生成底图','reference-video':'参考视频',brand:'品牌资料'}[a.type]}</span></div><div class="body"><h3>${esc(a.name)}</h3><p class="muted">${esc(data.scenes.find(s=>s.id===a.scene)?.name||'历史未分类 / 待归类')} · ${new Date(a.createdAt||a.updatedAt||Date.now()).toLocaleDateString()}</p><div class="asset-actions"><button data-asset-preview="${a.id}">查看</button><button data-favorite="${a.id}">${a.favorite?'★ 已收藏':'☆ 收藏'}</button><button data-use-asset="${a.id}">用于制作</button><button data-classify-asset="${a.id}">设置场景</button><button data-archive-asset="${a.id}">${a.archived?'恢复':'归档'}</button></div></div></article>`).join('')||'<div class="empty">没有符合条件的素材。</div>';document.querySelectorAll('[data-asset-preview]').forEach(b=>b.onclick=()=>{const a=assetById(b.dataset.assetPreview);a.type==='brand'?modal(`<h2>${esc(a.name)}</h2><p style="white-space:pre-wrap">${esc(a.materials)}</p>`):a.type==='reference-video'?modal(`<h2>${esc(a.name)}</h2>${a.videoUrl?`<video class="big-preview" controls preload="metadata" src="${esc(a.videoUrl)}"></video>`:`<img class="big-preview" src="${esc(a.previewUrl)}" alt="历史参考关键帧"><p>历史记录仅保存关键帧，原视频尚未保存在本机。</p>`}<a class="button primary" href="/replicate">用于爆款复刻</a>`):imagePreview(a.id,()=>assetsPage());});document.querySelectorAll('[data-favorite],[data-archive-asset]').forEach(b=>b.onclick=async()=>{const id=b.dataset.favorite||b.dataset.archiveAsset;await api('/studio/assets/'+id,{method:'PATCH',body:b.dataset.favorite?{favorite:!assetById(id).favorite}:{archived:!assetById(id).archived}});data=await api('/studio');render();});document.querySelectorAll('[data-classify-asset]').forEach(b=>b.onclick=()=>{const a=assetById(b.dataset.classifyAsset);modal(`<h2>设置素材场景</h2><label class="field">场景<select id="classifyScene"><option value="">待归类</option>${options(data.scenes,a.scene)}</select></label><button id="saveClassify" class="primary">保存</button>`);$('saveClassify').onclick=async()=>{await api('/studio/assets/'+a.id,{method:'PATCH',body:{scene:$('classifyScene').value}});data=await api('/studio');$('modal').close();assetsPage();};});document.querySelectorAll('[data-use-asset]').forEach(b=>b.onclick=()=>{const a=assetById(b.dataset.useAsset);if(a.type==='brand'){location.href='/studio?scene=story&brand='+a.id;return;}if(a.type==='reference-video'){location.href='/replicate?source='+a.id;return;}localStorage.setItem('studio:pendingAsset',a.id);location.href='/studio';});}
  document.querySelectorAll('[data-image-retry]').forEach(b=>b.onclick=async()=>{const [taskId,itemId]=b.dataset.imageRetry.split(':');const run=async externalId=>{try{await post(`/studio/image-tasks/${taskId}/items/${itemId}/retry`,{externalId});data=await api('/studio');$('modal').close();assetsPage();toast('已恢复底图任务，已成功的图片不会重做。');}catch(e){toast(e.message);}};if(b.dataset.unknown==='true'){modal('<h2>核对底图提交结果</h2><p>请在生成服务中查找已经提交的任务，填写其真实编号。此操作仅查询已有任务。</p><label class="field">上游编号<input id="imageExternalId"></label><button id="reconcileImage" class="primary">恢复查询</button>');$('reconcileImage').onclick=()=>run($('imageExternalId').value);}else await run('');});
  $('assetUpload').onclick=()=>uploadImage(()=>assetsPage());$('brandUpload').onclick=()=>{modal('<h2>添加品牌资料</h2><label class="field">主体名称<input id="newBrandName"></label><label class="field">已确认的宣传事实<textarea id="newBrandFacts"></textarea></label><button id="saveBrand" class="primary">保存资料</button>');$('saveBrand').onclick=async()=>{try{await post('/story-subjects',{name:$('newBrandName').value,materials:$('newBrandFacts').value});data=await api('/studio');$('modal').close();assetsPage();}catch(e){toast(e.message);}};};$('assetScene').onchange=e=>{assetScene=e.target.value;render();};$('assetSearch').oninput=e=>{query=e.target.value;render();};document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{filter=b.dataset.type;assetsPage();});render();
}
async function worksPage(){
  works=await api('/studio/works');
  $('app').innerHTML=title('我的作品','按模板与项目收纳，预览成片、核对失败任务，或继续调整制作。')+`<div class="toolbar"><input id="workSearch" placeholder="搜索项目或模板"><select id="workScene" style="width:150px"><option value="">全部场景</option>${options(data.scenes)}</select><select id="workStatus" style="width:170px"><option value="">全部状态</option>${options(Object.entries(statusNames).map(([id,name])=>({id,name})))}</select><input type="date" id="workDate" style="width:160px" aria-label="生成日期"></div><div id="workGroups"></div>`;
  function render(){
    const list=works.filter(j=>(!params.get('project')||j.projectId===params.get('project'))&&(!$('workScene').value||j.sceneId===$('workScene').value)&&(!$('workStatus').value||j.status===$('workStatus').value)&&(!$('workDate').value||j.createdAt.startsWith($('workDate').value))&&((j.templateName||j.actionTemplate?.name||'历史未分类')+(data.projects.find(p=>p.id===j.projectId)?.name||j.batchId)).includes($('workSearch').value));
    const groups=new Map();for(const j of list){const key=(j.templateId||j.actionTemplate?.id||j.skillId||'historical')+':'+(j.projectId||j.batchId);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(j);}
    const renderProjectGroup=([key,jobs],groupIndex)=>{const first=jobs[0],complete=jobs.filter(j=>j.status==='complete'&&j.outputs?.length),failed=jobs.filter(j=>j.status==='error'),running=jobs.filter(j=>['running','waiting','submitting'].includes(j.status)),queued=jobs.filter(j=>j.status==='queued');return `<details class="work-group" ${groupIndex===0?'open':''}><summary><strong>${esc(first.templateName||first.actionTemplate?.name||'历史未分类')}</strong><span>${esc(data.projects.find(p=>p.id===first.projectId)?.name||'历史批次 '+first.batchId?.slice(0,8))}</span><span class="badge">${complete.length} 已完成</span><span class="badge">${running.length} 生成中 · ${queued.length} 排队</span><span class="badge status-error">${failed.length} 失败</span><button data-group-download="${esc(key)}" ${!complete.length?'disabled':''}>下载已完成</button><button data-group-retry="${esc(key)}" ${!failed.length?'disabled':''}>重试失败</button></summary><div class="work-grid">${jobs.map(j=>`<article class="work"><figure>${j.status==='complete'?`<img data-video-poster="${j.id}" data-video-src="/api/video/${j.id}?preview=1" loading="lazy" alt="成片封面"><button data-open-work="${j.id}">▷ 预览</button><input type="checkbox" aria-label="选择作品" data-work-check="${j.id}" ${selectedWorks.has(j.id)?'checked':''}>`:`<span>${esc(statusNames[j.status]||j.status)}</span>`}</figure><div class="body"><h3>${String(j.slotIndex!==undefined?j.slotIndex+1:j.index||1).padStart(2,'0')} ${j.isTrial?'· 试片':''}</h3><span class="badge status-${j.status}">${esc(statusNames[j.status]||j.status)}</span><p class="muted">${j.duration||'—'} 秒 · ${new Date(j.createdAt).toLocaleString()}</p><button data-open-work="${j.id}">详情</button>${j.status==='error'?`<button data-retry="${j.id}">重试</button>`:''}${j.status==='queued'?`<button data-cancel="${j.id}">取消排队</button>`:''}</div></article>`).join('')}</div></details>`;};
    const byTemplate=new Map();for(const entry of groups){const j=entry[1][0],key=j.templateId||`${j.skillId||'historical'}:${j.templateName||'历史未分类'}`;if(!byTemplate.has(key))byTemplate.set(key,[]);byTemplate.get(key).push(entry);}
    $('workGroups').innerHTML=[...byTemplate].map(([key,projects],templateIndex)=>{const all=projects.flatMap(([,jobs])=>jobs),first=all[0];return `<details class="template-cluster" ${templateIndex===0?'open':''}><summary><h2>${esc(first.templateName||first.actionTemplate?.name||'历史未分类')} <span class="badge">${all.length} 条 · ${projects.length} 个项目 / 历史批次</span></h2><span class="badge">${all.filter(j=>j.status==='complete').length} 已完成 · ${all.filter(j=>j.status==='error').length} 失败</span><button data-template-download="${esc(key)}">下载该模板已完成作品</button></summary>${projects.map(renderProjectGroup).join('')}</details>`;}).join('')||'<div class="empty">没有符合条件的作品。制作任务提交后会出现在这里。</div>';
    document.querySelectorAll('[data-template-download]').forEach(b=>b.onclick=e=>{e.preventDefault();downloadWorks(byTemplate.get(b.dataset.templateDownload).flatMap(([,jobs])=>jobs.map(j=>j.id)));});
    document.querySelectorAll('[data-work-check]').forEach(e=>e.onchange=()=>{e.checked?selectedWorks.add(e.dataset.workCheck):selectedWorks.delete(e.dataset.workCheck);workBottom();});
    document.querySelectorAll('[data-open-work]').forEach(b=>b.onclick=()=>workDetail(works.find(j=>j.id===b.dataset.openWork)));
    document.querySelectorAll('[data-retry],[data-cancel]').forEach(b=>b.onclick=async()=>{try{await post('/studio/jobs/'+(b.dataset.retry||b.dataset.cancel)+'/'+(b.dataset.retry?'retry':'cancel'),{});works=await api('/studio/works');render();}catch(e){toast(e.message);}});
    document.querySelectorAll('[data-group-download]').forEach(b=>b.onclick=e=>{e.preventDefault();downloadWorks(groups.get(b.dataset.groupDownload).map(j=>j.id));});
    document.querySelectorAll('[data-group-retry]').forEach(b=>b.onclick=async e=>{e.preventDefault();try{for(const j of groups.get(b.dataset.groupRetry).filter(j=>j.status==='error'))await post('/studio/jobs/'+j.id+'/retry',{});works=await api('/studio/works');render();}catch(e){toast(e.message);}});
    window.VideoCards?.observe($('workGroups'));workBottom();
  }
  for(const id of ['workSearch','workScene','workStatus','workDate'])$(id).oninput=render;render();
  clearInterval(worksPage.timer);worksPage.timer=setInterval(async()=>{if($('modal').open)return;const focused=document.activeElement?.id,values=Object.fromEntries(['workSearch','workScene','workStatus','workDate'].map(id=>[id,$(id).value]));works=await api('/studio/works');render();if(focused)$(focused)?.focus();},6000);
}
function workBottom(){bottom(`<div><strong>已选 ${selectedWorks.size} 条</strong><small>仅下载已完成的成片，输入图片保留在我的素材。</small></div><button id="downloadSelected" class="primary" ${!selectedWorks.size?'disabled':''}>下载所选作品</button>`);$('downloadSelected').onclick=()=>downloadWorks([...selectedWorks]);}
async function downloadWorks(ids){try{const run=await post('/studio/downloads',{jobIds:ids,requestId:crypto.randomUUID()});modal(`<h2>准备作品下载</h2><p id="downloadState">正在保存 ${run.total} 条成片到本机…${run.excluded?'已排除 '+run.excluded+' 条未完成作品。':''}</p><a id="archiveLink" class="button primary" hidden>下载作品 ZIP</a>`);async function poll(){const state=await api('/studio/downloads/'+run.id);if($('downloadState'))$('downloadState').textContent=`已保存 ${state.complete}/${state.total} 条。${state.errors.map(e=>e.message).join('；')}`;if(state.ready&&$('archiveLink')){$('archiveLink').hidden=false;$('archiveLink').href='/api/studio/downloads/'+run.id+'/archive';}else if(state.running)setTimeout(poll,2500);}poll();}catch(e){toast(e.message);}}
function workDetail(j){const p=data.projects.find(p=>p.id===j.projectId),refs=j.referenceImageIds||[j.referenceId].filter(Boolean);modal(`<h2>${esc(j.templateName||j.actionTemplate?.name||'历史作品')} · 画面 ${j.slotIndex!==undefined?j.slotIndex+1:j.index||1}</h2><div class="preview-layout"><div>${j.status==='complete'?`<video controls playsinline preload="metadata" src="/api/video/${j.id}?preview=1"></video>`:`<div class="empty">${esc(statusNames[j.status]||j.status)}<p>${esc(j.error||'')}</p></div>`}</div><div><h3>${esc(statusNames[j.status]||j.status)}</h3><p>${esc(p?.name||'历史批次')} · ${j.duration} 秒 · ${j.ratio||'9:16'}</p><div class="row">${j.status==='complete'?`<a class="button primary" href="/api/video/${j.id}?download=1">下载 MP4</a>${j.sceneId==='story'?'<button id="renderSubtitles">字幕渲染与下载</button>':''}`:''}<button id="redoWork">调整内容并重做</button>${['complete','review_pending'].includes(j.status)&&!p?'<button id="reviewLegacy">查看原批次试片确认</button>':''}${j.isTrial&&j.status==='complete'?'<button id="adoptTrial">采纳这条试片</button>':''}</div>${j.status==='needs_review'?'<label class="field">核对上游任务编号<input id="externalId" placeholder="从账号池核对成功后填写编号"></label><button id="reconcileWork">查询并关联已有任务</button>':''}<h3>使用的底图</h3><div class="thumbs">${refs.map(id=>`<img src="/api/references/${id}/image" alt="来源底图">`).join('')}</div><details class="detail-block"><summary>视频描述</summary><p style="white-space:pre-wrap">${esc(j.prompt)}</p></details><details class="detail-block"><summary>制作设置与模板版本</summary><p>版本 ${j.templateVersion||'历史记录无版本'} · ${esc(j.templateSnapshot?.name||j.actionTemplate?.name||'待归类')}</p><p>${esc(j.resolution)} · ${esc(j.referenceMode)}</p></details><details class="detail-block"><summary>执行记录与账号</summary><p>${esc(j.providerProgress?.accountName||'上游未返回账号信息')}</p>${(j.attemptHistory||[]).map(a=>`<p>尝试 ${a.number}：${esc(a.status)} · ${esc(a.error||'')}</p>`).join('')}</details><p class="notice">重新制作会保留当前作品，便于后续对比。</p></div></div>`);
  if($('renderSubtitles'))$('renderSubtitles').onclick=()=>{$('modal').close();window.StorySubtitles.open(j.id);};
  if($('reconcileWork'))$('reconcileWork').onclick=async()=>{try{const updated=await post('/studio/jobs/'+j.id+'/reconcile',{externalId:$('externalId').value});workDetail(updated);toast('已查询上游并关联任务，没有新提交。');}catch(e){toast(e.message);}};
  if($('adoptTrial'))$('adoptTrial').onclick=async()=>{try{await post('/studio/projects/'+p.id+'/adopt',{jobId:j.id});toast('已采纳，批量提交时自动抵扣这条。');$('modal').close();}catch(e){toast(e.message);}};
  if($('reviewLegacy'))$('reviewLegacy').onclick=async()=>{try{const review=await api('/batches/'+j.batchId+'/review');if(!review.required||review.approved)throw Error('该历史批次没有待确认的试片');modal(`<h2>确认原批次试片</h2><video class="big-preview" controls preload="metadata" src="/api/video/${review.trialJobId}?preview=1"></video><p>采纳已完成试片后，原批次仅继续剩余 ${review.remaining} 条；原试片不会重复生成。</p><button id="approveLegacy" class="primary" ${!review.ready?'disabled':''}>确认试片并继续剩余任务</button>`);$('approveLegacy').onclick=async()=>{try{$('approveLegacy').disabled=true;await post('/batches/'+j.batchId+'/review',{});$('modal').close();worksPage();}catch(e){toast(e.message);$('approveLegacy').disabled=false;}};}catch(e){toast(e.message);}};
  if($('redoWork'))$('redoWork').onclick=async()=>{try{let source;if(p)source=await api('/studio/projects/'+p.id);else {let t=data.templates.find(t=>t.id===j.templateId||t.actionId===j.actionId&&t.packId===j.packId||t.name===j.templateName);if(!t)t=await post('/studio/templates',{name:(j.templateName||'历史作品')+' · 重做模板',description:j.prompt||'请补充视频内容',scene:j.sceneId||'',duration:j.duration||5,actions:[],imageRules:'核对原作品底图，按调整后的内容制作。',source:'my'});source={name:(j.templateName||'历史作品')+' · 重做',scene:j.sceneId||t.scene||'',brandName:j.subjectSnapshot?.name||'',brandFacts:j.subjectSnapshot?.materials||'',plans:[{id:j.planId,templateId:t.id,count:1,duration:j.duration||t.duration,videoRoute:j.videoRoute||'doubao',resolution:j.resolution,imageIds:refs,mapping:'common',creativeBrief:'',content:j.prompt||'',prompts:[],snapshot:j.templateSnapshot||t}]};}const clone=structuredClone(source);delete clone.id;clone.name+=' · 重做';clone.plans=clone.plans.filter(plan=>plan.id===j.planId).map(plan=>({...plan,id:crypto.randomUUID(),count:1,imageIds:refs,mapping:refs.length>1?'shots':'common',shotImages:[refs],prompts:[]}));const created=await post('/studio/projects',clone);location.href='/studio?scene='+created.scene+'&project='+created.id;}catch(e){toast(e.message);}};
}
async function accountsPage(){
  const info=await api('/doubao'),rawItems=info.accountItems||[],jobs=await api('/studio/works'),items=rawItems.map(a=>{const active=jobs.find(j=>['running','waiting','submitting'].includes(j.status)&&j.providerProgress?.accountId===a.id);return {...a,name:a.display_name||a.nickname||a.id,status:active?'busy':a.status,current_task:active?.templateName||active?.actionTemplate?.name||'',last_checked_at:a.last_verified_at};}),available=items.filter(a=>a.enabled&&a.status==='active'&&!(a.video_quota_total!=null&&Number(a.video_quota_used)>=Number(a.video_quota_total)));
  $('app').innerHTML=title('豆包账号池','任务自动分配可用账号，未提交的任务可以暂停或取消。')+`<div class="row"><button id="addAccount" class="primary">＋ 添加 / 登录账号</button><button id="refreshAccounts">刷新状态</button><a class="button" href="/legacy?tab=accounts">会话导入与高级管理</a></div><div class="metrics">${[{name:'总账号',count:items.length},{name:'可用',count:available.length},{name:'忙碌',count:items.filter(a=>a.status==='busy').length},{name:'需处理',count:items.filter(a=>!a.enabled||a.status!=='active').length}].map(m=>`<div class="metric">${m.name}<strong>${m.count}</strong></div>`).join('')}</div>${!info.connected?`<div class="notice warning">${esc(info.message)}</div>`:''}<table><thead><tr><th>账号名称</th><th>状态</th><th>当前任务</th><th>最近检查</th><th>操作</th></tr></thead><tbody>${items.map(a=>`<tr><td>${esc(a.name||a.id)}</td><td>${!a.enabled?'暂停':{active:'可用',busy:'忙碌',expired:'需登录',invalid:'需登录'}[a.status]||'状态待确认'}</td><td>${esc(a.current_task_id||a.current_task||'未返回任务信息')}</td><td>${esc(a.last_checked_at||a.updated_at||'未返回')}</td><td><button data-toggle-account="${a.id}">${a.enabled?'暂停':'启用'}</button></td></tr>`).join('')||'<tr><td colspan="5">暂无账号。队列会保留已提交的制作设置。</td></tr>'}</tbody></table><section class="sourcebar"><div class="row"><h2>任务队列 · ${jobs.filter(j=>j.status==='queued').length} 项等待</h2><button id="pauseQueue">${data.settings.paused?'恢复调度':'暂停新任务调度'}</button></div><table><thead><tr><th>模板 / 项目</th><th>时长</th><th>状态</th><th>操作</th></tr></thead><tbody>${jobs.filter(j=>['queued','needs_review'].includes(j.status)).map(j=>`<tr><td>${esc(j.templateName||j.actionTemplate?.name||'历史任务')}</td><td>${j.duration} 秒</td><td>${esc(statusNames[j.status])}</td><td>${j.status==='queued'?`<button data-cancel-queue="${j.id}">取消</button>`:`<button data-reconcile="${j.id}">查询上游</button>`}</td></tr>`).join('')}</tbody></table></section>`;
  accountsPage.timer ||= setInterval(()=>{if(!$('modal').open)accountsPage().catch(e=>toast(e.message));},8000);
  $('refreshAccounts').onclick=accountsPage;$('pauseQueue').onclick=async()=>{data.settings=await post('/studio/settings',{paused:!data.settings.paused});accountsPage();};
  document.querySelectorAll('[data-toggle-account]').forEach(b=>b.onclick=async()=>{try{const a=items.find(a=>String(a.id)===b.dataset.toggleAccount);await api('/doubao/accounts/'+a.id,{method:'PATCH',body:{enabled:!a.enabled}});accountsPage();}catch(e){toast(e.message);}});
  document.querySelectorAll('[data-cancel-queue],[data-reconcile]').forEach(b=>b.onclick=async()=>{try{await post('/studio/jobs/'+(b.dataset.cancelQueue||b.dataset.reconcile)+'/'+(b.dataset.cancelQueue?'cancel':'reconcile'),{});accountsPage();}catch(e){toast(e.message);}});
  $('addAccount').onclick=async()=>{try{const login=await post('/doubao/login-attempts',{});modal(`<h2>登录豆包账号</h2><p>请在豆包管理器的登录窗口完成扫码。</p><p id="loginState">${esc(login.status||'等待登录')}</p><a class="button" href="/legacy?tab=accounts">打开账号管理</a>`);}catch(e){toast(e.message);}};
}
async function settingsPage(){
  const connection=await api('/studio/connections');
  $('app').innerHTML=title('设置','生成能力来自当前已配置的服务，具体时长与画质以制作时的可用选项为准。')+`<div class="toolbar"><button class="primary">模型与连接</button><button id="preferences">生成偏好</button></div><div class="settings-grid"><section class="card body"><h2>▧ 底图生成服务</h2><p>用于人物、场景与视频起始画面的图片生成。</p><span class="badge">${data.keyframeConfigured?'已配置 · 未检测':'未配置'}</span><label class="field">服务密钥<input type="password" value="${data.keyframeConfigured?'********':''}" readonly aria-label="已保存密钥状态"></label><p class="muted">密钥由后端读取本机受保护配置，不会返回到页面。</p><details><summary>连接高级设置</summary><p>服务地址、模型与密钥在本机配置中管理。</p><button id="openImageConfig">编辑服务连接</button></details></section><section class="card body"><h2>▷ 视频生成服务</h2><p>默认使用豆包账号池自动分配。</p><label class="field">可用服务<select id="defaultRoute">${options(data.routes.filter(r=>r.configured),data.settings.defaultRoute||'doubao')}</select></label><p>已配置 ${data.routes.filter(r=>r.configured).length} 个服务</p><details><summary>服务能力与模型</summary>${data.routes.map(r=>`<p><strong>${esc(r.name)}</strong> · ${r.configured?'已配置':'未配置'}<br><span class="muted">${esc(r.model)} · ${esc(r.resolutions.join(' / '))} · ${esc((r.duration.values||[r.duration.min,r.duration.max]).join(' / '))} 秒</span></p>`).join('')}</details><button id="testConnection">测试连接</button><p id="connectionResult">未检测</p></section></div><div class="notice">连接检查不会创建图片或视频任务。当前服务未提供的费用、额度和进度不会推测显示。</div>`;
  $('testConnection').onclick=async()=>{try{$('testConnection').disabled=true;const result=await post('/studio/connection-test',{});$('connectionResult').textContent=result.video.message+'；API 服务：'+(result.api.message||JSON.stringify(result.api));}catch(e){$('connectionResult').textContent=e.message;}finally{$('testConnection').disabled=false;}};
  $('openImageConfig').onclick=()=>{
    const definitions=[['APIMART_BASE_URL','图片 / 视频服务地址'],['IMAGE_MODEL','图片模型'],['VIDEO_MODEL','视频模型'],['PROMPT_MODEL','提示词模型'],['SCENE_ANALYSIS_MODEL','图片分析模型'],['TEXT_PROVIDER','文本服务（tokendance 或留空）'],['TOKENDANCE_CHAT_BASE_URL','文本服务地址'],['TOKENDANCE_PROMPT_MODEL','文本模型'],['TOKENDANCE_VISION_MODEL','视觉模型']];
    modal('<h2>编辑服务连接</h2>'+definitions.map(([key,name])=>`<label class="field">${name}<input data-config="${key}" value="${esc(connection.values[key])}"></label>`).join('')+`<label class="field">图片 / 视频服务密钥（留空保留现有密钥）<input id="newVideoKey" type="password" autocomplete="new-password" placeholder="${connection.videoKeyConfigured?'已保存 · 输入可更新':'未配置'}"></label><label class="field">文本服务密钥（留空保留现有密钥）<input id="newTextKey" type="password" autocomplete="new-password" placeholder="${connection.textKeyConfigured?'已保存 · 输入可更新':'未配置'}"></label><p class="notice">密钥使用当前 Windows 用户加密保存，页面不会读取已保存的密钥。已有任务继续使用原有上游编号查询。</p><button id="saveConnections" class="primary">保存连接</button>`);
    $('saveConnections').onclick=async()=>{try{$('saveConnections').disabled=true;await post('/studio/connections',{values:Object.fromEntries([...document.querySelectorAll('[data-config]')].map(e=>[e.dataset.config,e.value])),videoKey:$('newVideoKey').value,textKey:$('newTextKey').value});data=await api('/studio');$('modal').close();settingsPage();toast('服务配置已保存并载入。');}catch(e){toast(e.message);$('saveConnections').disabled=false;}};
  };
  $('defaultRoute').onchange=async()=>{data.settings=await post('/studio/settings',{defaultRoute:$('defaultRoute').value});toast('默认生成服务已保存。');};
  $('preferences').onclick=()=>modal('<h2>生成偏好</h2><p>视频默认 5 秒，短剧默认 15 秒。每个模板独立设置，服务不支持的推荐时长会提示你选择。</p><p>豆包账号自动分配。试片可选，已采纳的有效试片抵扣一条成片。</p>');
}
async function init(){try{
  data=await api('/studio');document.querySelector(`nav a[href="${page}"]`)?.classList.add('active');if(page==='/settings')document.querySelector('.settings-link').classList.add('active');
  if(page==='/templates'){templateCenter();return;}if(page==='/assets'){assetsPage();return;}if(page==='/works'){await worksPage();return;}if(page==='/accounts'){await accountsPage();return;}if(page==='/settings'){await settingsPage();return;}
  scene=params.get('scene');if(!scene&&!params.get('template')&&!params.get('project')){home();return;}
  project=params.get('project')?await api('/studio/projects/'+params.get('project')):await post('/studio/projects',{scene:scene||'',name:(data.scenes.find(s=>s.id===scene)?.name||'模板')+'制作',plans:[]});
  scene=project.scene;
  if(!params.has('project')){const url=new URL(location.href);url.searchParams.set('project',project.id);history.replaceState(null,'',url);}
  if(params.get('template')&&!project.plans.length){const t=templateById(params.get('template'));if(t){scene=t.scene;project.scene=scene;const route=data.routes.find(r=>r.id===(data.settings.defaultRoute||'doubao'));project.plans.push({id:crypto.randomUUID(),templateId:t.id,count:1,duration:t.duration,videoRoute:route.id,resolution:route.resolutions[0],mapping:t.mapping,imageIds:localStorage.getItem('studio:pendingAsset')?[localStorage.getItem('studio:pendingAsset')]:[],rows:[],shotImages:[],creativeBrief:'',content:'',snapshot:t,prompts:[]});await save();}}
  if(params.get('brand')){const brand=assetById(params.get('brand'));if(brand?.type==='brand'){project.brandName=brand.name;project.brandFacts=brand.materials;await save();}}
  view=project.stage||'templates';renderStudio();const draftId=localStorage.getItem('studio:draft:'+project.id)||project.promptTaskId;if(draftId){view='prompts';renderStudio();pollDraft(draftId);}const imageTask=localStorage.getItem('studio:images:'+project.id)||data.imageTasks?.find(t=>t.projectId===project.id&&t.status==='running')?.id;if(imageTask)pollImages(imageTask);
}catch(e){$('app').innerHTML=`<div class="notice warning">${esc(e.message)}</div>`;}}
window.addEventListener('pagehide',()=>{if(project?.id){const snapshot=structuredClone(project);for(const p of snapshot.plans){delete p.snapshot.versions;delete p.prompts;}navigator.sendBeacon('/api/studio/projects',new Blob([JSON.stringify(snapshot)],{type:'application/json'}));}if(project?.id&&project.plans.every(p=>p.prompts.length===p.count&&p.prompts.every(Boolean)))navigator.sendBeacon(`/api/studio/projects/${project.id}/prompts`,new Blob([JSON.stringify({plans:project.plans.filter(p=>p.prompts.length===p.count&&p.prompts.every(Boolean)).map(p=>({id:p.id,prompts:p.prompts,scriptConfirmed:p.scriptConfirmed}))})],{type:'application/json'}));});
$('modal').addEventListener('close',()=>{for(const video of $('modal').querySelectorAll('video'))video.pause();});
init();
